import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    Fused kernel version: matmul -> group norm -> leaky ReLU -> x + x
    """
    def __init__(self, input_size, hidden_size, num_groups, eps=1e-5, negative_slope=0.01):
        super().__init__()
        self.fc = torch.nn.Linear(input_size, hidden_size, bias=True)
        self.gn = torch.nn.GroupNorm(num_groups=num_groups, num_channels=hidden_size, eps=eps)
        self.negative_slope = float(negative_slope)

    def forward(self, x):
        # 调用自定义融合算子：x, weight, bias, gamma, beta, groups, eps, negative_slope
        return custom_ops_lib.matmul_group_norm_leaky_relu_sum_custom(
            x, self.fc.weight, self.fc.bias, self.gn.weight, self.gn.bias, self.gn.num_groups, float(self.gn.eps), self.negative_slope
        )
'''
